
create table public.universities (
  id uuid primary key default gen_random_uuid(),
  name text not null unique,
  country text not null default 'Sweden',
  city text,
  featured boolean not null default false,
  sort_order int not null default 100
);
create table public.skills (
  id uuid primary key default gen_random_uuid(),
  name text not null unique,
  category text not null check (category in ('Programming','Embedded and Hardware','Data and AI','Security','Engineering tools','Business','Languages','Soft skills'))
);
create table public.companies (
  id uuid primary key default gen_random_uuid(),
  name text not null unique,
  slug text not null unique,
  org_number text,
  careers_url text,
  website text,
  city text,
  cities text[] not null default '{}',
  industry text,
  tier int not null default 2 check (tier between 1 and 4),
  description text,
  source_type text not null default 'auto' check (source_type in ('auto','jobtech','greenhouse','lever','workable','teamtailor','varbi','reachmee','jobylon','ashby','workday','custom_html')),
  ats_identifier text,
  scrape_enabled boolean not null default true,
  scrape_disabled_reason text,
  last_scraped_at timestamptz,
  last_status text,
  consecutive_failures int not null default 0,
  is_watched boolean not null default false,
  typical_roles text[] not null default '{}',
  hiring_period text,
  watch_note text,
  last_posting_at timestamptz,
  lat double precision,
  lng double precision,
  created_at timestamptz not null default now()
);
create table public.jobs (
  id uuid primary key default gen_random_uuid(),
  company_id uuid not null references public.companies(id) on delete cascade,
  title text not null,
  looking_for text not null check (looking_for in ('thesis','internship','graduate','student_job','full_time')),
  role_type text not null,
  city text not null check (city in ('linkoping','stockholm','gothenburg','other','remote')),
  location_label text not null,
  lat double precision,
  lng double precision,
  work_mode text not null default 'onsite' check (work_mode in ('onsite','hybrid','remote')),
  summary text,
  key_requirements text[] not null default '{}',
  required_skills text[] not null default '{}',
  nice_skills text[] not null default '{}',
  min_level text check (min_level in ('Bachelor','Master','PhD')),
  fields text[] not null default '{}',
  description text,
  source text not null default 'seed',
  source_url text,
  external_id text,
  posted_at timestamptz not null default now(),
  deadline date,
  status text not null default 'open' check (status in ('open','closed')),
  missed_runs int not null default 0,
  first_seen_at timestamptz not null default now(),
  last_seen_at timestamptz not null default now(),
  created_at timestamptz not null default now()
);
create unique index jobs_company_external on public.jobs(company_id, coalesce(external_id, source_url, id::text));
create index jobs_status_idx on public.jobs(status, posted_at desc);

grant select on public.universities, public.skills, public.companies, public.jobs to anon, authenticated;
grant all on public.universities, public.skills, public.companies, public.jobs to service_role;
alter table public.universities enable row level security;
alter table public.skills enable row level security;
alter table public.companies enable row level security;
alter table public.jobs enable row level security;
create policy "public read" on public.universities for select using (true);
create policy "public read" on public.skills for select using (true);
create policy "public read" on public.companies for select using (true);
create policy "public read" on public.jobs for select using (true);




-- Jobs
